import { describe, expect, it } from 'vitest';
import { resolveAsrConfig, WhisperCppAsrAdapter } from '@jarvis/speech';
import { synthesiseToWav } from './speech-synthesis.ts';
import { UtteranceService } from './utterance-service.ts';

/**
 * The connected loop, with real engines at both ends.
 *
 * A spoken question is generated by the local synthesiser (a real utterance, not a stored
 * fixture), transcribed by the installed ARM64 whisper.cpp build, and answered with real
 * local speech again. This spans both services as the Kernel composes them, so a passing
 * adapter unit test cannot stand in for it.
 *
 * Opt-in, because it spawns the recogniser and the Windows synthesiser:
 *   JARVIS_VOICE_LOOP_REAL=1 pnpm vitest run apps/core/src/kernel/voice
 */

const enabled = process.env.JARVIS_VOICE_LOOP_REAL === '1';
const config = resolveAsrConfig();

function wavFacts(buffer: Buffer) {
  return {
    riff: buffer.subarray(0, 4).toString() === 'RIFF',
    wave: buffer.subarray(8, 12).toString() === 'WAVE',
    channels: buffer.readUInt16LE(22),
    rate: buffer.readUInt32LE(24),
    bits: buffer.readUInt16LE(34),
    seconds: buffer.readUInt32LE(40) / (buffer.readUInt16LE(32) || 1) / (buffer.readUInt32LE(24) || 1),
  };
}

describe.skipIf(!enabled)('connected voice loop (real engines)', () => {
  it('recognises a locally spoken sentence and synthesises the reply', async () => {
    expect(config.engine).toBe('whisper-cpp');
    expect(config.readiness.ready, `engine not ready: ${config.readiness.detail ?? ''}`).toBe(true);

    const service = new UtteranceService({ adapter: () => new WhisperCppAsrAdapter(config.config!), timeoutMs: 30_000 });

    // 1. A real spoken question, produced on this machine.
    const spoken = await synthesiseToWav('Good evening Jarvis. Can you hear me clearly?');
    const input = wavFacts(spoken);
    expect(input).toMatchObject({ riff: true, wave: true, channels: 1, rate: 16_000, bits: 16 });
    expect(input.seconds).toBeGreaterThan(1);

    // 2. Real recognition through the same service the endpoint uses.
    const heard = await service.transcribe({ body: spoken, contentType: 'audio/wav' });
    expect(heard.problem).toBeUndefined();
    expect(heard.ok).toBe(true);
    expect((heard.transcript ?? '').toLowerCase()).toContain('hear me clearly');
    expect(heard.latencyMs).toBeGreaterThan(0);
    expect(heard.audioMs).toBeGreaterThan(1000);

    // 3. A real spoken answer the browser can decode.
    const reply = await synthesiseToWav('Yes. I can hear you clearly.');
    const output = wavFacts(reply);
    expect(output).toMatchObject({ riff: true, wave: true, channels: 1, rate: 16_000, bits: 16 });
    expect(output.seconds).toBeGreaterThan(0.4);
    expect(reply.byteLength).toBeLessThan(4_000_000);
  }, 90_000);

  it('reports silence instead of inventing a transcript', async () => {
    const service = new UtteranceService({ adapter: () => new WhisperCppAsrAdapter(config.config!), timeoutMs: 30_000 });
    const quiet = Buffer.alloc(16_000 * 2); // one second of digital silence
    const result = await service.transcribe({ body: quiet, contentType: 'application/octet-stream' });
    expect(result.transcript ?? '').toBe('');
  }, 60_000);
});
